-- ============================================================
-- 南山科转通 · PostgreSQL 结构（单库 tech_transfer，21 表）
-- 来源：migrations/001~005（MySQL 实际业务结构）
--      + tools/platform-crawler、tools/szte-crawler 爬虫存量表
--        （资本域 3 表，原独立库 nanshan_capital，2026-09-03 合并进本库）
-- 翻译约定：
--   * AUTO_INCREMENT            → BIGINT GENERATED BY DEFAULT AS IDENTITY
--   * DATETIME                  → TIMESTAMPTZ
--   * JSON                      → JSONB
--   * TINYINT(1)                → BOOLEAN
--   * ON UPDATE CURRENT_TIMESTAMP → 触发器 set_updated_at()
--   * FULLTEXT KEY              → GIN(to_tsvector('simple', ...))
--   * external_identity 唯一键保持 (issuer, tenant_id, external_subject)
-- 可重复执行（IF NOT EXISTS / OR REPLACE / DROP TRIGGER IF EXISTS）
-- 执行方式：
--   psql -h 127.0.0.1 -U postgres -d tech_transfer -v ON_ERROR_STOP=1 -f 001_tech_transfer_schema.sql
-- ============================================================

BEGIN;

-- ------------------------------------------------------------
-- updated_at 自动维护函数（等价 MySQL ON UPDATE CURRENT_TIMESTAMP）
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

-- ========================================================
-- 身份域（源：001_identity_domain.sql）
-- ========================================================

-- 1. app_user —— 科转通本地用户
CREATE TABLE IF NOT EXISTS public.app_user (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_no    VARCHAR(32)  NOT NULL,
    status     VARCHAR(16)  NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at TIMESTAMPTZ  DEFAULT NULL,
    CONSTRAINT uk_user_no UNIQUE (user_no)
);

COMMENT ON TABLE  public.app_user IS '科转通本地用户表';
COMMENT ON COLUMN public.app_user.user_no IS '用户编号（对外展示）';
COMMENT ON COLUMN public.app_user.status IS 'active/disabled';
COMMENT ON COLUMN public.app_user.deleted_at IS '软删除时间';

DROP TRIGGER IF EXISTS trg_app_user_updated_at ON public.app_user;
CREATE TRIGGER trg_app_user_updated_at BEFORE UPDATE ON public.app_user
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 2. external_identity —— 外部身份映射
CREATE TABLE IF NOT EXISTS public.external_identity (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id               BIGINT       NOT NULL,
    issuer                VARCHAR(32)  NOT NULL,
    tenant_id             VARCHAR(32)  NOT NULL DEFAULT 'default',
    external_subject      VARCHAR(128) NOT NULL,
    display_name_snapshot VARCHAR(64)  DEFAULT NULL,
    linked_at             TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    unlinked_at           TIMESTAMPTZ  DEFAULT NULL,
    CONSTRAINT uk_identity UNIQUE (issuer, tenant_id, external_subject),
    CONSTRAINT fk_ext_identity_user FOREIGN KEY (user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_identity_user ON public.external_identity(user_id);

COMMENT ON TABLE  public.external_identity IS '外部身份映射表';
COMMENT ON COLUMN public.external_identity.issuer IS 'local-dev/WECHAT/AINANSHAN 等';
COMMENT ON COLUMN public.external_identity.tenant_id IS '租户标识，默认 default';
COMMENT ON COLUMN public.external_identity.external_subject IS '外部平台唯一主体 ID';
COMMENT ON CONSTRAINT uk_identity ON public.external_identity
    IS '同一签发方+租户+主体只允许映射一条';

-- 3. user_profile —— 用户业务资料（一对一）
CREATE TABLE IF NOT EXISTS public.user_profile (
    user_id      BIGINT       NOT NULL PRIMARY KEY,
    display_name VARCHAR(64)  DEFAULT NULL,
    user_type    VARCHAR(32)  DEFAULT NULL,
    phone        VARCHAR(32)  DEFAULT NULL,
    email        VARCHAR(128) DEFAULT NULL,
    org_id       BIGINT       DEFAULT NULL,
    org_title    VARCHAR(64)  DEFAULT NULL,
    version      INT          NOT NULL DEFAULT 1,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_profile_user FOREIGN KEY (user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_profile_org ON public.user_profile(org_id);

COMMENT ON TABLE public.user_profile IS '用户业务资料（与 app_user 一对一）';
COMMENT ON COLUMN public.user_profile.version IS '乐观锁版本号';

DROP TRIGGER IF EXISTS trg_user_profile_updated_at ON public.user_profile;
CREATE TRIGGER trg_user_profile_updated_at BEFORE UPDATE ON public.user_profile
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 4. user_role —— 用户角色
CREATE TABLE IF NOT EXISTS public.user_role (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    BIGINT      NOT NULL,
    role_code  VARCHAR(32) NOT NULL DEFAULT 'user',
    granted_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_user_role UNIQUE (user_id, role_code),
    CONSTRAINT fk_role_user FOREIGN KEY (user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE
);

COMMENT ON TABLE public.user_role IS '用户角色表';

-- 5. auth_session —— 会话吊销登记
CREATE TABLE IF NOT EXISTS public.auth_session (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT       NOT NULL,
    refresh_jti VARCHAR(64)  NOT NULL,
    status      VARCHAR(16)  NOT NULL DEFAULT 'active',
    issued_at   TIMESTAMPTZ  NOT NULL,
    expires_at  TIMESTAMPTZ  NOT NULL,
    revoked_at  TIMESTAMPTZ  DEFAULT NULL,
    consumed_at TIMESTAMPTZ  DEFAULT NULL,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_auth_session_jti UNIQUE (refresh_jti)
);

CREATE INDEX IF NOT EXISTS idx_auth_session_user ON public.auth_session(user_id, status);

COMMENT ON TABLE public.auth_session IS '会话吊销登记表';

DROP TRIGGER IF EXISTS trg_auth_session_updated_at ON public.auth_session;
CREATE TRIGGER trg_auth_session_updated_at BEFORE UPDATE ON public.auth_session
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- ========================================================
-- 成果域（源：002_achievement_domain.sql）
-- ========================================================

-- 6. organization —— 来源机构
CREATE TABLE IF NOT EXISTS public.organization (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_name   VARCHAR(128) NOT NULL,
    org_type   VARCHAR(32)  DEFAULT NULL,
    intro      TEXT         DEFAULT NULL,
    region     VARCHAR(64)  DEFAULT NULL,
    status     VARCHAR(16)  NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at TIMESTAMPTZ  DEFAULT NULL,
    CONSTRAINT uk_org_name_active UNIQUE (org_name, status)
);

COMMENT ON TABLE  public.organization IS '来源机构表';
COMMENT ON COLUMN public.organization.deleted_at IS '软删除时间';

DROP TRIGGER IF EXISTS trg_organization_updated_at ON public.organization;
CREATE TRIGGER trg_organization_updated_at BEFORE UPDATE ON public.organization
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 7. achievement_category —— 成果分类（字典表）
CREATE TABLE IF NOT EXISTS public.achievement_category (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code       VARCHAR(32) NOT NULL,
    name       VARCHAR(64) NOT NULL,
    sort_order INT         NOT NULL DEFAULT 0,
    enabled    BOOLEAN     NOT NULL DEFAULT TRUE,
    CONSTRAINT uk_cat_code UNIQUE (code)
);

COMMENT ON TABLE public.achievement_category IS '成果分类字典表';

-- 8. achievement —— 成果主表
-- 状态机（06 §4.2）：published/offline + reject_reason（存量简化模型）
CREATE TABLE IF NOT EXISTS public.achievement (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_user_id      BIGINT        NOT NULL,
    org_id             BIGINT        DEFAULT NULL,
    source_org_name    VARCHAR(128)  DEFAULT NULL,
    title              VARCHAR(200)  NOT NULL,
    category_id        BIGINT        DEFAULT NULL,
    tech_intro         TEXT          DEFAULT NULL,
    tech_route         TEXT          DEFAULT NULL,
    maturity_level     VARCHAR(16)   NOT NULL DEFAULT '02_lab',
    maturity_desc      VARCHAR(255)  DEFAULT NULL,
    application_fields JSONB         DEFAULT NULL,
    innovation_points  JSONB         DEFAULT NULL,
    pricing_mode       VARCHAR(32)   NOT NULL DEFAULT 'negotiable',
    price_min_wan      NUMERIC(14,2) DEFAULT NULL,
    price_max_wan      NUMERIC(14,2) DEFAULT NULL,
    contact_name       VARCHAR(64)   DEFAULT NULL,
    contact_title      VARCHAR(64)   DEFAULT NULL,
    contact_phone      VARCHAR(32)   DEFAULT NULL,
    contact_email      VARCHAR(128)  DEFAULT NULL,
    contact_wechat     VARCHAR(64)   DEFAULT NULL,
    status             VARCHAR(16)   NOT NULL DEFAULT 'published',
    reject_reason      VARCHAR(500)  DEFAULT NULL,
    version            INT           NOT NULL DEFAULT 1,
    view_count         BIGINT        NOT NULL DEFAULT 0,
    published_at       TIMESTAMPTZ   DEFAULT NULL,
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at         TIMESTAMPTZ   DEFAULT NULL,
    CONSTRAINT fk_ach_owner FOREIGN KEY (owner_user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_ach_org FOREIGN KEY (org_id)
        REFERENCES public.organization(id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_ach_cat FOREIGN KEY (category_id)
        REFERENCES public.achievement_category(id) ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_ach_status_pub ON public.achievement(status, published_at);
CREATE INDEX IF NOT EXISTS idx_ach_owner      ON public.achievement(owner_user_id, status);
CREATE INDEX IF NOT EXISTS idx_ach_org        ON public.achievement(org_id);
CREATE INDEX IF NOT EXISTS idx_ach_title      ON public.achievement(title);
CREATE INDEX IF NOT EXISTS idx_ach_category   ON public.achievement(category_id);

-- MySQL FULLTEXT(title, tech_intro) 的 PostgreSQL 等价（simple 分词，中文按需换 zhparser）
CREATE INDEX IF NOT EXISTS ft_ach_text ON public.achievement
    USING GIN (to_tsvector('simple', title || ' ' || coalesce(tech_intro, '')));

COMMENT ON TABLE  public.achievement IS '科技成果主表';
COMMENT ON COLUMN public.achievement.maturity_level IS '01_paper/02_lab/03_pilot/04_mass 等';
COMMENT ON COLUMN public.achievement.pricing_mode IS 'negotiable/priced';
COMMENT ON COLUMN public.achievement.version IS '乐观锁版本号';
COMMENT ON COLUMN public.achievement.deleted_at IS '软删除时间';

DROP TRIGGER IF EXISTS trg_achievement_updated_at ON public.achievement;
CREATE TRIGGER trg_achievement_updated_at BEFORE UPDATE ON public.achievement
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 9. inventor —— 成果完成人
CREATE TABLE IF NOT EXISTS public.inventor (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(64)  NOT NULL,
    org_name    VARCHAR(128) DEFAULT NULL,
    person_type VARCHAR(16)  DEFAULT NULL,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_inventor UNIQUE (name, org_name)
);

COMMENT ON TABLE public.inventor IS '成果完成人表';

-- 10. achievement_inventor —— 成果-完成人关联
CREATE TABLE IF NOT EXISTS public.achievement_inventor (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    achievement_id BIGINT       NOT NULL,
    inventor_id    BIGINT       NOT NULL,
    sort_order     INT          NOT NULL DEFAULT 0,
    contribution   VARCHAR(255) DEFAULT NULL,
    CONSTRAINT uk_ach_inv UNIQUE (achievement_id, inventor_id),
    CONSTRAINT fk_ai_achievement FOREIGN KEY (achievement_id)
        REFERENCES public.achievement(id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_ai_inventor FOREIGN KEY (inventor_id)
        REFERENCES public.inventor(id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_inv ON public.achievement_inventor(inventor_id);

COMMENT ON TABLE public.achievement_inventor IS '成果-完成人关联表';

-- ========================================================
-- 审计域（源：003_audit_log.sql）
-- ========================================================

-- 11. audit_log —— 审计日志（只 INSERT 不 UPDATE/DELETE）
CREATE TABLE IF NOT EXISTS public.audit_log (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_user_id BIGINT      DEFAULT NULL,
    actor_user_no VARCHAR(32) DEFAULT NULL,
    action        VARCHAR(64) NOT NULL,
    resource_type VARCHAR(32) NOT NULL,
    resource_id   VARCHAR(64) DEFAULT NULL,
    details       JSONB       DEFAULT NULL,
    ip_address    VARCHAR(45) DEFAULT NULL,
    request_id    VARCHAR(64) DEFAULT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_audit_actor FOREIGN KEY (actor_user_id)
        REFERENCES public.app_user(id) ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_audit_actor    ON public.audit_log(actor_user_id);
CREATE INDEX IF NOT EXISTS idx_audit_resource ON public.audit_log(resource_type, resource_id);
CREATE INDEX IF NOT EXISTS idx_audit_created  ON public.audit_log(created_at);

COMMENT ON TABLE  public.audit_log IS '审计日志，只 INSERT 不 UPDATE/DELETE';
COMMENT ON COLUMN public.audit_log.actor_user_id IS '操作者用户ID（系统操作为 NULL）';
COMMENT ON COLUMN public.audit_log.action IS '操作类型，如 create_achievement / approve_demand';
COMMENT ON COLUMN public.audit_log.resource_id IS '资源ID（字符串）';
COMMENT ON COLUMN public.audit_log.request_id IS '请求ID，关联 X-Request-Id';

-- ========================================================
-- 需求域（源：004_demand_domain.sql）
-- ========================================================

-- 12. demand_category —— 需求分类（字典表）
CREATE TABLE IF NOT EXISTS public.demand_category (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code       VARCHAR(32) NOT NULL,
    name       VARCHAR(64) NOT NULL,
    sort_order INT         NOT NULL DEFAULT 0,
    enabled    BOOLEAN     NOT NULL DEFAULT TRUE,
    CONSTRAINT uk_dmdcat_code UNIQUE (code)
);

COMMENT ON TABLE public.demand_category IS '需求分类字典表';

-- 13. demand_tag —— 需求标签（字典表）
CREATE TABLE IF NOT EXISTS public.demand_tag (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code    VARCHAR(64) NOT NULL,
    name    VARCHAR(64) NOT NULL,
    enabled BOOLEAN     NOT NULL DEFAULT TRUE,
    CONSTRAINT uk_dmdtag_code UNIQUE (code)
);

COMMENT ON TABLE public.demand_tag IS '需求标签字典表';

-- 14. demand —— 需求主表
-- 状态机（06 §5.2）：draft → pending_review → published → matched → closed
--                  draft/rejected → pending_review（重新提交）
--                  published → cancelled / closed（未匹配直接关闭）
CREATE TABLE IF NOT EXISTS public.demand (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_user_id     BIGINT        NOT NULL,
    org_id            BIGINT        DEFAULT NULL,
    title             VARCHAR(200)  NOT NULL,
    category_id       BIGINT        DEFAULT NULL,
    description       TEXT          NOT NULL,
    region            VARCHAR(64)   DEFAULT NULL,
    coop_mode         JSONB         DEFAULT NULL,
    budget_min_wan    NUMERIC(14,2) DEFAULT NULL,
    budget_max_wan    NUMERIC(14,2) DEFAULT NULL,
    budget_negotiable BOOLEAN       NOT NULL DEFAULT FALSE,
    expect_deadline   DATE          DEFAULT NULL,
    deadline_desc     VARCHAR(128)  DEFAULT NULL,
    contact_name      VARCHAR(64)   DEFAULT NULL,
    contact_title     VARCHAR(64)   DEFAULT NULL,
    contact_phone     VARCHAR(32)   DEFAULT NULL,
    contact_email     VARCHAR(128)  DEFAULT NULL,
    contact_wechat    VARCHAR(64)   DEFAULT NULL,
    status            VARCHAR(16)   NOT NULL DEFAULT 'draft',
    reject_reason     VARCHAR(500)  DEFAULT NULL,
    version           INT           NOT NULL DEFAULT 1,
    published_at      TIMESTAMPTZ   DEFAULT NULL,
    created_at        TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at        TIMESTAMPTZ   DEFAULT NULL,
    CONSTRAINT chk_dmd_budget CHECK (
        budget_min_wan IS NULL
        OR budget_max_wan IS NULL
        OR budget_min_wan <= budget_max_wan
    ),
    CONSTRAINT fk_dmd_owner FOREIGN KEY (owner_user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_dmd_org FOREIGN KEY (org_id)
        REFERENCES public.organization(id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_dmd_cat FOREIGN KEY (category_id)
        REFERENCES public.demand_category(id) ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_dmd_status_published ON public.demand(status, published_at);
CREATE INDEX IF NOT EXISTS idx_dmd_owner            ON public.demand(owner_user_id, status);
CREATE INDEX IF NOT EXISTS idx_dmd_org              ON public.demand(org_id);
CREATE INDEX IF NOT EXISTS idx_dmd_title            ON public.demand(title);
CREATE INDEX IF NOT EXISTS idx_dmd_category         ON public.demand(category_id);

-- MySQL FULLTEXT(title, description) 的 PostgreSQL 等价
CREATE INDEX IF NOT EXISTS ft_dmd_text ON public.demand
    USING GIN (to_tsvector('simple', title || ' ' || description));

COMMENT ON TABLE  public.demand IS '技术需求主表';
COMMENT ON COLUMN public.demand.coop_mode IS '合作方式（JSON 数组）';
COMMENT ON COLUMN public.demand.budget_min_wan IS '预算下限（万元）';
COMMENT ON COLUMN public.demand.budget_max_wan IS '预算上限（万元）';
COMMENT ON COLUMN public.demand.version IS '乐观锁版本号';
COMMENT ON COLUMN public.demand.deleted_at IS '软删除时间';

DROP TRIGGER IF EXISTS trg_demand_updated_at ON public.demand;
CREATE TRIGGER trg_demand_updated_at BEFORE UPDATE ON public.demand
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 15. demand_tag_relation —— 需求-标签关联
CREATE TABLE IF NOT EXISTS public.demand_tag_relation (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    demand_id BIGINT NOT NULL,
    tag_id    BIGINT NOT NULL,
    CONSTRAINT uk_dmd_tag UNIQUE (demand_id, tag_id),
    CONSTRAINT fk_dmdtr_demand FOREIGN KEY (demand_id)
        REFERENCES public.demand(id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_dmdtr_tag FOREIGN KEY (tag_id)
        REFERENCES public.demand_tag(id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_dmdtr_tag ON public.demand_tag_relation(tag_id);

COMMENT ON TABLE public.demand_tag_relation IS '需求-标签关联表';

-- ========================================================
-- 交互域（源：005_interaction_domain.sql）
-- ========================================================

-- 16. favorite —— 收藏（取消即物理 DELETE，审计走 audit_log）
CREATE TABLE IF NOT EXISTS public.favorite (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT      NOT NULL,
    target_type VARCHAR(16) NOT NULL,
    target_id   BIGINT      NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_fav UNIQUE (user_id, target_type, target_id),
    CONSTRAINT fk_fav_user FOREIGN KEY (user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_fav_target ON public.favorite(target_type, target_id);

COMMENT ON TABLE  public.favorite IS '用户收藏表';
COMMENT ON COLUMN public.favorite.target_type IS 'achievement / demand';

-- 17. cooperation_intent —— 对接意向
-- uk_coop_active 说明：同一发起人对同一目标同时只能有一条活跃意向，
-- 终态记录可重复。active_flag 为生成列：活跃(pending/accepted/confirmed)=1，
-- 终态=NULL；PostgreSQL 唯一索引默认 NULLS DISTINCT，与 MySQL 语义一致。
-- 活跃重复发起另由服务端校验兜底。
CREATE TABLE IF NOT EXISTS public.cooperation_intent (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    initiator_user_id    BIGINT        NOT NULL,
    target_type          VARCHAR(16)   NOT NULL,
    target_id            BIGINT        NOT NULL,
    target_owner_user_id BIGINT        NOT NULL,
    message              VARCHAR(1000) DEFAULT NULL,
    status               VARCHAR(16)   NOT NULL DEFAULT 'pending',
    active_flag          INT GENERATED ALWAYS AS (
                             CASE WHEN status IN ('pending', 'accepted', 'confirmed')
                                  THEN 1 END
                         ) STORED,
    version              INT           NOT NULL DEFAULT 1,
    accepted_at          TIMESTAMPTZ   DEFAULT NULL,
    confirmed_at         TIMESTAMPTZ   DEFAULT NULL,
    completed_at         TIMESTAMPTZ   DEFAULT NULL,
    closed_at            TIMESTAMPTZ   DEFAULT NULL,
    created_at           TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_coop_active UNIQUE (initiator_user_id, target_type, target_id, active_flag),
    CONSTRAINT fk_coop_initiator FOREIGN KEY (initiator_user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_coop_owner FOREIGN KEY (target_owner_user_id)
        REFERENCES public.app_user(id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_coop_target_owner ON public.cooperation_intent(target_owner_user_id, status);
CREATE INDEX IF NOT EXISTS idx_coop_initiator    ON public.cooperation_intent(initiator_user_id, status);
CREATE INDEX IF NOT EXISTS idx_coop_target       ON public.cooperation_intent(target_type, target_id, status);

COMMENT ON TABLE  public.cooperation_intent IS '对接意向表';
COMMENT ON COLUMN public.cooperation_intent.initiator_user_id IS '发起人（服务端注入）';
COMMENT ON COLUMN public.cooperation_intent.target_type IS 'achievement / demand';
COMMENT ON COLUMN public.cooperation_intent.target_owner_user_id IS '被发起方（冗余自目标表）';
COMMENT ON COLUMN public.cooperation_intent.status IS 'pending/accepted/rejected/confirmed/completed/cancelled';
COMMENT ON COLUMN public.cooperation_intent.active_flag IS '生成列：活跃=1，终态=NULL';
COMMENT ON COLUMN public.cooperation_intent.closed_at IS '终态（rejected/cancelled）关闭时间';

DROP TRIGGER IF EXISTS trg_cooperation_intent_updated_at ON public.cooperation_intent;
CREATE TRIGGER trg_cooperation_intent_updated_at BEFORE UPDATE ON public.cooperation_intent
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 18. cooperation_event —— 对接事件（状态事实源）
CREATE TABLE IF NOT EXISTS public.cooperation_event (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    intent_id        BIGINT       NOT NULL,
    event_type       VARCHAR(32)  NOT NULL,
    from_status      VARCHAR(16)  DEFAULT NULL,
    to_status        VARCHAR(16)  NOT NULL,
    operator_user_id BIGINT       NOT NULL,
    operator_role    VARCHAR(16)  NOT NULL,
    remark           VARCHAR(500) DEFAULT NULL,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_coop_event_intent FOREIGN KEY (intent_id)
        REFERENCES public.cooperation_intent(id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_coop_event_intent ON public.cooperation_event(intent_id, id);

COMMENT ON TABLE  public.cooperation_event IS '对接事件表（状态事实源）';
COMMENT ON COLUMN public.cooperation_event.event_type IS 'created/accepted/rejected/confirmed/cancelled/completed/auto_rejected';
COMMENT ON COLUMN public.cooperation_event.operator_user_id IS '取自服务端 IdentityContext';
COMMENT ON COLUMN public.cooperation_event.operator_role IS 'initiator/target_owner/admin/system';

-- ========================================================
-- 资本域（源：tools/platform-crawler、tools/szte-crawler 爬虫存量表，
--          原独立库 nanshan_capital，2026-09-03 合并进本库）
-- ========================================================

-- 19. platform_base —— 概念验证中心/中小试基地库
CREATE TABLE IF NOT EXISTS public.platform_base (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    serial_no      INT          NOT NULL,
    platform_name  VARCHAR(255) NOT NULL,
    platform_type  VARCHAR(64)  NOT NULL DEFAULT '',
    support_unit   VARCHAR(255) NOT NULL DEFAULT '',
    platform_fun   TEXT         DEFAULT NULL,
    contact_person VARCHAR(64)  NOT NULL DEFAULT '',
    contact_mobile VARCHAR(64)  NOT NULL DEFAULT '',
    source_status  INT          DEFAULT NULL,
    order_num      INT          DEFAULT NULL,
    source_site    VARCHAR(128) NOT NULL DEFAULT 'first-net.cn',
    fetched_at     TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_serial_no UNIQUE (serial_no)
);

CREATE INDEX IF NOT EXISTS idx_platform_type ON public.platform_base(platform_type);
CREATE INDEX IF NOT EXISTS idx_platform_name ON public.platform_base(platform_name);

COMMENT ON TABLE  public.platform_base IS '概念验证中心/中小试基地库';
COMMENT ON COLUMN public.platform_base.serial_no IS '序号（源站）';
COMMENT ON COLUMN public.platform_base.platform_type IS '平台类型（概念验证中心/中小试基地）';
COMMENT ON COLUMN public.platform_base.support_unit IS '依托单位';
COMMENT ON COLUMN public.platform_base.platform_fun IS '平台功能';
COMMENT ON COLUMN public.platform_base.source_site IS '数据来源站点';

DROP TRIGGER IF EXISTS trg_platform_base_updated_at ON public.platform_base;
CREATE TRIGGER trg_platform_base_updated_at BEFORE UPDATE ON public.platform_base
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 20. ip_service_org —— 知识产权融资信息服务-专业服务机构（银行融资）
CREATE TABLE IF NOT EXISTS public.ip_service_org (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account      VARCHAR(128) NOT NULL DEFAULT '',
    org_name     VARCHAR(255) NOT NULL,
    intro        TEXT         DEFAULT NULL,
    detail_info  TEXT         DEFAULT NULL,
    label        VARCHAR(64)  NOT NULL DEFAULT '',
    user_type    VARCHAR(64)  NOT NULL DEFAULT '',
    logo_file_id VARCHAR(64)  NOT NULL DEFAULT '',
    sort_order   INT          NOT NULL DEFAULT 0,
    source_site  VARCHAR(128) NOT NULL DEFAULT 'szte.com',
    source_api   VARCHAR(255) NOT NULL DEFAULT '',
    fetched_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_account UNIQUE (account)
);

CREATE INDEX IF NOT EXISTS idx_org_name ON public.ip_service_org(org_name);

COMMENT ON TABLE  public.ip_service_org IS '知识产权融资信息服务-专业服务机构（银行融资）';
COMMENT ON COLUMN public.ip_service_org.account IS '源站账号标识';
COMMENT ON COLUMN public.ip_service_org.intro IS '公司简介（列表/悬停）';
COMMENT ON COLUMN public.ip_service_org.detail_info IS '详细信息（详情页正文）';
COMMENT ON COLUMN public.ip_service_org.logo_file_id IS '源站 logo 文件 id，经 /api/file/{id} 代理';

DROP TRIGGER IF EXISTS trg_ip_service_org_updated_at ON public.ip_service_org;
CREATE TRIGGER trg_ip_service_org_updated_at BEFORE UPDATE ON public.ip_service_org
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- 21. featured_invest_org —— 特色投资机构一览（投资机构）
CREATE TABLE IF NOT EXISTS public.featured_invest_org (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    org_name           VARCHAR(255) NOT NULL,
    intro              TEXT         DEFAULT NULL,
    detail_info        TEXT         DEFAULT NULL,
    logo_file_id       VARCHAR(64)  NOT NULL DEFAULT '',
    detail_activity_id INT          DEFAULT NULL,
    sort_order         INT          NOT NULL DEFAULT 0,
    source_site        VARCHAR(128) NOT NULL DEFAULT 'szte.com',
    source_page        VARCHAR(255) NOT NULL DEFAULT '',
    fetched_at         TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_org_name UNIQUE (org_name)
);

CREATE INDEX IF NOT EXISTS idx_sort_order ON public.featured_invest_org(sort_order);

COMMENT ON TABLE  public.featured_invest_org IS '特色投资机构一览（投资机构）';
COMMENT ON COLUMN public.featured_invest_org.intro IS '公司简介（列表/悬停卡片）';
COMMENT ON COLUMN public.featured_invest_org.detail_info IS '详细信息（详情页正文）';
COMMENT ON COLUMN public.featured_invest_org.logo_file_id IS '源站 logo/配图文件 id，经 /api/file/{id} 代理';

DROP TRIGGER IF EXISTS trg_featured_invest_org_updated_at ON public.featured_invest_org;
CREATE TRIGGER trg_featured_invest_org_updated_at BEFORE UPDATE ON public.featured_invest_org
    FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

COMMIT;
